# Diagram geometry is traced from the enlarged source, rather than replacing
# these unanswered exercises with computed readings.
def vernier(start,zero):
    ticks=''.join(f'<path d="M{20+i*5.6} 58v{-24 if i%10==0 else -15 if i%5==0 else -8}"/>' for i in range(56))
    labels=''.join(f'<text x="{20+i*56}" y="24" text-anchor="middle">{start+i}</text>' for i in range(6))
    vt=''.join(f'<path d="M{zero+i*5.04} 58v{20 if i in (0,10) else 12 if i==5 else 7}"/>' for i in range(11))
    return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 340 125" role="img" aria-label="Vernier calliper reading exercise; source scale labels {start} through {start+5}"><g stroke="currentColor" fill="currentColor" font-size="15" font-family="sans-serif">{ticks}{labels}{vt}<path d="M10 58H330M{zero-4} 58V89H{zero+54}V58M45 115H295" fill="none"/></g></svg>'
def screw(edge,labels):
    ticks=''.join(f'<path d="M{40+i*14} 65v{-32 if i%10==0 else -20 if i%2==0 else 12}"/>' for i in range(23) if 40+i*14<edge)
    mainlabels=''.join(f'<text x="{40+i*28}" y="22">{i}</text>' for i in (0,5,10) if 40+i*28<edge)
    circular=''.join(f'<path d="M{edge} {y}l{18 if v%5==0 else 10} -3"/>'+(f'<text x="{edge+25}" y="{y+4}">{v}</text>' if v%5==0 else '') for v,y in labels)
    return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 440 150" role="img" aria-label="Micrometer screw gauge reading exercise"><path d="M{edge} 20H425V112H{edge}Z" fill="#e5e7eb" stroke="currentColor"/><g stroke="currentColor" fill="currentColor" font-size="15" font-family="sans-serif">{ticks}{mainlabels}{circular}<path d="M22 65H{edge+22}M50 139H400"/></g></svg>'
